scwin.listSync = function() {

    txb_jongmokName.setValue("");
    const sbmOptions = {
        id : "sbm_dts_jongmok",
        action : "/submitperson.do",
        ref : "",
        target : "dts_jongmok=body.content",
        submitDoneHandler : scwin.sbm_dts_jongmok_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

/********************************************** 
 * 함수명   : Jongmok()
 * 설명       : 가나다라..검색
 ***********************************************/
scwin.Jongmok = function(prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";

    dts_jongmok.removeColumnFilterAll(); // TODO Stage2: 필터 검토 - skw="" 이므로 전체표시(원본: UseFilter=true; Filter())
    dts_jongmok.sort("SUBMIT_OBLG_ABBRV", 0);
    let cnt = -1;
    for (let i = 0; i < dts_jongmok.getRowCount(); i++) {
        let name = dts_jongmok.getCellData(i, "SUBMIT_OBLG_ABBRV").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }
    if (cnt >= 0) {
        grd_jongmok.setFocusedCell(cnt, "SUBMIT_OBLG_ABBRV"); // TODO Stage2: RowPosition 세터/스크롤 동작 검토(원본 Rowposition=cnt+11 후 cnt)
    }

    grd_jongmok.focus();
};

/********************************************** 
 * 함수명   : JongmokName()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokName = function(keyCode) {
    //if(keyCode==13) on_close();
    dts_jongmok.sort("SUBMIT_OBLG_ABBRV", 0);
    let cnt = -1;
    const len = txb_jongmokName.getValue().length;
    const txtVal = txb_jongmokName.getValue().toUpperCase();
    for (let i = 0; i < dts_jongmok.getRowCount(); i++) {
        let name = dts_jongmok.getCellData(i, "SUBMIT_OBLG_ABBRV").substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }
    if (cnt >= 0) {
        grd_jongmok.setFocusedCell(cnt, "SUBMIT_OBLG_ABBRV"); // TODO Stage2: RowPosition 세터/스크롤 동작 검토(원본 Rowposition=cnt+11 후 cnt)
    }
};

/********************************************** 
 * 함수명   : JongmokSearch()
 * 설명       : 종목명검색
 ***********************************************/
$c.stockSearch.JongmokSearch = function() {
    scwin.skw = txb_jongmokName.getValue();
    // TODO Stage2: 필터 검토 - skw 부분일치(COM_ABBRV/OLD_COM_ABBRV) 커스텀 필터 재구현 필요(원본: UseFilter=true; Filter())
    grd_jongmok.setFocusedCell(0, "SUBMIT_OBLG_ABBRV"); // TODO Stage2: RowPosition 세터 검토(원본 Rowposition=1)
};

/********************************************** 
 * 함수명   : Confirm()
 * 설명       : 부모창으로 종목코드 전달
 ***********************************************/
scwin.Confirm = function() {
    //frame.Provider("../").종목코드id
    const pJongCode = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "SUBMIT_OBLG_ABBRV");
    const pJongNm = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "DISCLS_SUBMITPRN_TP_CD_NM");
    $c.cm.submitSearch_Rtn(pJongCode, pJongNm);

    $c.win.closePopup();
};

scwin.code1Sync = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_code1_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};



