scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox_01(panel_1);
    $c.libRoundPanel.PanelToGroupBox_02(panel_2);
    const sbmOptions = {
        id : "sbm_dts_jongmok",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_jongmok=body.content",
        submitDoneHandler : scwin.sbm_dts_jongmok_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    const sbmOptions2 = {
        id : "sbm_MxDataSet_code1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
